#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled kernel for a Conv3d whose kernel is (K,K,1):
// treated as an independent 2D (K x K) convolution applied per-depth-slice,
// with general stride/padding/dilation/groups applied uniformly to H, W, and D
// (kernel size along D is 1, so D acts purely as a "select-with-stride/padding" dim).
template <int TILE_H, int TILE_W, int REG_TILE, int COUT_TILE>
__global__ void conv2d_depthslice_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ Bs,
    float* __restrict__ Y,
    int N, int Cin, int H, int Win, int D,
    int Cout, int Hout, int Wout, int Dout,
    int K, int stride, int padding, int dilation, int groups,
    int TileInH, int TileInW)
{
  extern __shared__ float smem[];
  const int Cin_per_group  = Cin / groups;
  const int Cout_per_group = Cout / groups;
  float* sIn_ptr = smem;
  float* sW_ptr  = smem + (size_t)Cin * TileInH * TileInW;
  auto sIn = make_tensor(make_smem_ptr(sIn_ptr),
                          make_shape(Cin, TileInH, TileInW),
                          make_stride(TileInH * TileInW, TileInW, 1));
  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(COUT_TILE, Cin_per_group, K, K),
                         make_stride(Cin_per_group * K * K, K * K, K, 1));
  const int nd = blockIdx.z;
  const int n  = nd / Dout;
  const int od = nd % Dout;
  const int id = od * stride - padding; // depth kernel size = 1
  const int tile_h0 = blockIdx.y * TILE_H;
  const int tile_w0 = blockIdx.x * TILE_W;
  constexpr int THREADS_H = TILE_H / REG_TILE;
  constexpr int THREADS_W = TILE_W / REG_TILE;
  const int blockThreads = THREADS_H * THREADS_W;
  const int tx = threadIdx.x % THREADS_W;
  const int ty = threadIdx.x / THREADS_W;
  const bool depth_valid = (id >= 0 && id < D);
  // Strides for X: (N, Cin, H, Win, D) contiguous, D fastest
  const int64_t sXd = 1;
  const int64_t sXw = D;
  const int64_t sXh = (int64_t)Win * D;
  const int64_t sXc = (int64_t)H * sXh;
  const int64_t sXn = (int64_t)Cin * sXc;
  // Strides for Y: (N, Cout, Hout, Wout, Dout) contiguous
  const int64_t sYd = 1;
  const int64_t sYw = Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYc = (int64_t)Hout * sYh;
  const int64_t sYn = (int64_t)Cout * sYc;
  const int base_ih = tile_h0 * stride - padding;
  const int base_iw = tile_w0 * stride - padding;
  const int total_load = Cin * TileInH * TileInW;
  if (depth_valid) {
    const float* Xbase = X + (int64_t)n * sXn + (int64_t)id * sXd;
    for (int idx = threadIdx.x; idx < total_load; idx += blockThreads) {
      int c   = idx / (TileInH * TileInW);
      int rem = idx % (TileInH * TileInW);
      int r   = rem / TileInW;
      int cc  = rem % TileInW;
      int ih  = base_ih + r;
      int iw  = base_iw + cc;
      float v = 0.0f;
      if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
        v = Xbase[(int64_t)c * sXc + (int64_t)ih * sXh + (int64_t)iw * sXw];
      }
      sIn(c, r, cc) = v;
    }
  } else {
    for (int idx = threadIdx.x; idx < total_load; idx += blockThreads) {
      int c   = idx / (TileInH * TileInW);
      int rem = idx % (TileInH * TileInW);
      int r   = rem / TileInW;
      int cc  = rem % TileInW;
      sIn(c, r, cc) = 0.0f;
    }
  }
  __syncthreads();
  const int oh_base = tile_h0 + ty * REG_TILE;
  const int ow_base = tile_w0 + tx * REG_TILE;
  float* Ybase = Y + (int64_t)n * sYn + (int64_t)od * sYd;
  // Tile over Cout so that only a chunk of the weight tensor is staged in
  // shared memory at a time. This shrinks the per-block dynamic shared
  // memory footprint (which was previously limiting occupancy) while
  // still reusing the staged input tile across all output channels.
  const int cin_per_group_k2 = Cin_per_group * K * K;
  for (int co0 = 0; co0 < Cout; co0 += COUT_TILE) {
    const int cout_this = (Cout - co0) < COUT_TILE ? (Cout - co0) : COUT_TILE;
    const int total_w = cout_this * cin_per_group_k2;
    for (int idx = threadIdx.x; idx < total_w; idx += blockThreads) {
      int co_local = idx / cin_per_group_k2;
      int rem      = idx % cin_per_group_k2;
      sW_ptr[idx] = Wt[(int64_t)(co0 + co_local) * cin_per_group_k2 + rem];
    }
    __syncthreads();
    for (int co_local = 0; co_local < cout_this; ++co_local) {
      const int co = co0 + co_local;
      const int g = co / Cout_per_group;
      const int ci_start = g * Cin_per_group;
      float acc[REG_TILE][REG_TILE];
      #pragma unroll
      for (int rh = 0; rh < REG_TILE; ++rh) {
        #pragma unroll
        for (int rw = 0; rw < REG_TILE; ++rw) {
          acc[rh][rw] = (Bs != nullptr) ? Bs[co] : 0.0f;
        }
      }
      for (int cir = 0; cir < Cin_per_group; ++cir) {
        const int ci = ci_start + cir;
        for (int kh = 0; kh < K; ++kh) {
          for (int kw = 0; kw < K; ++kw) {
            float wv = sW(co_local, cir, kh, kw);
            #pragma unroll
            for (int rh = 0; rh < REG_TILE; ++rh) {
              int lr = (ty * REG_TILE + rh) * stride + kh * dilation;
              #pragma unroll
              for (int rw = 0; rw < REG_TILE; ++rw) {
                int lc = (tx * REG_TILE + rw) * stride + kw * dilation;
                acc[rh][rw] += sIn(ci, lr, lc) * wv;
              }
            }
          }
        }
      }
      #pragma unroll
      for (int rh = 0; rh < REG_TILE; ++rh) {
        const int oh = oh_base + rh;
        if (oh >= Hout) continue;
        #pragma unroll
        for (int rw = 0; rw < REG_TILE; ++rw) {
          const int ow = ow_base + rw;
          if (ow >= Wout) continue;
          Ybase[(int64_t)co * sYc + (int64_t)oh * sYh + (int64_t)ow * sYw] = acc[rh][rw];
        }
      }
    }
    __syncthreads(); // ensure sW is fully consumed before next chunk overwrites it
  }
}

torch::Tensor conv3d_hw_forward(torch::Tensor x,
                                 torch::Tensor weight,
                                 c10::optional<torch::Tensor> bias,
                                 int stride, int padding, int dilation, int groups) {
