  // shared memory at a time. This shrinks the per-block dynamic shared
  // memory footprint (which was previously limiting occupancy) while
  // still reusing the staged input tile across all output channels.
  const int cin_per_group_k2 = Cin_per_group * K * K;
  for (int co0 = 0; co0 < Cout; co0 += COUT_TILE) {
    const int cout_this = (Cout - co0) < COUT_TILE ? (Cout - co0) : COUT_TILE;
    const int total_w = cout_this * cin_per_group_k2;
    for (int idx = threadIdx.x; idx < total_w; idx += blockThreads) {
      int co_local = idx / cin_per_group_k2;
      int rem      = idx % cin_per_group_k2;
      sW_ptr[idx] = Wt[(int64_t)(co0 + co_local) * cin_per_group_k2 + rem];
    }
    __syncthreads();
    for (int co_local = 0; co_local < cout_this; ++co_local) {
      const int co = co0 + co_local;
      const int g = co / Cout_per_group;
      const int ci_start = g * Cin_per_group;
      float acc[REG_TILE][REG_TILE];
      #pragma unroll
      for (int rh = 0; rh < REG_TILE; ++rh) {
        #pragma unroll
        for (int rw = 0; rw < REG_TILE; ++rw) {
          acc[rh][rw] = (Bs != nullptr) ? Bs[co] : 0.0f;
        }
      }
      for (int cir = 0; cir < Cin_per_group; ++cir) {
        const int ci = ci_start + cir;
        for (int kh = 0; kh < K; ++kh) {
          for (int kw = 0; kw < K; ++kw) {
            float wv = sW(co_local, cir, kh, kw);
            #pragma unroll
            for (int rh = 0; rh < REG_TILE; ++rh) {
              int lr = (ty * REG_TILE + rh) * stride + kh * dilation;
              #pragma unroll
              for (int rw = 0; rw < REG_TILE; ++rw) {
                int lc = (tx * REG_TILE + rw) * stride + kw * dilation;
                acc[rh][rw] += sIn(ci, lr, lc) * wv;
              }
            }
          }
        }
      }
      #pragma unroll
      for (int rh = 0; rh < REG_TILE; ++rh) {
        const int oh = oh_base + rh;
        if (oh >= Hout) continue;
        #pragma unroll
        for (int rw = 0; rw < REG_TILE; ++rw) {
          const int ow = ow_base + rw;
          if (ow >= Wout) continue;
          Ybase[(int64_t)co * sYc + (int64_t)oh * sYh + (int64_t)ow * sYw] = acc[rh][rw];
        }
      }
    }
    __syncthreads(); // ensure sW is fully consumed before next chunk overwrites it
  }
}

