            (unsigned)(N * Dout));
  const int cout_tile_used = (int)std::min<int64_t>(COUT_TILE, Cout);
  size_t shmem_bytes = ((size_t)Cin * TileInH * TileInW +
                         (size_t)cout_tile_used * Cin_per_group * K * K) * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_depthslice_kernel<TILE_H, TILE_W, REG_TILE, COUT_TILE><<<grid, block, shmem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win, (int)D,
      (int)Cout, (int)Hout, (int)Wout, (int)Dout,
      (int)K, stride, padding, dilation, groups,
